"""Clemency, rehabilitation and historical security-measure clauses."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
CP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del2848compilado.htm'
LEP='https://www.planalto.gov.br/ccivil_03/leis/l7210.htm'
CF='https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
S617='https://scon.stj.jus.br/SCON/pesquisar.jsp?b=SUMU&livre=SUMULA+INPATH%28TIPO%29+AND+617+INPATH%28NUM%29'
T1367='https://www.stj.jus.br/sites/portalp/Paginas/Comunicacao/Noticias/2026/29052026-Repetitivo-define-que-pena-por-crime-cometido-sob-livramento-condicional-comeca-apos-fim-do-beneficio.aspx'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,CP,LEP,*links])
add(733,'Extinção do livramento exige integrar CP89–90, LEP146 e Súmula617/STJ.', ['Sem suspensão ou revogação antes do fim, considerar orientação sumulada.', 'Tema1367/STJ de2026: nova pena por delito do período inicia após fim do benefício na hipótese examinada.', 'Não cumprir simultaneamente duas penas não unificadas.'], 'Não presumir prorrogação automática por notícia de crime; verificar ato de suspensão/revogação e situação do período.', 'Período acaba sem suspensão ou revogação; examina-se extinção conforme Súmula617.', 'Preso por delito cometido no período, depois extinto sem suspensão/revogação, tem termo da nova execução examinado pelo Tema1367.', ['Mera notícia prorroga automaticamente todo livramento? Não.', 'Tema1367 afasta cumprimento simultâneo de penas não unificadas? Sim.'], 'Extinção do livramento','Conclusão do benefício segundo regime legal e jurisprudencial.',[S617,T1367])
add(734,'Graça ou indulto individual segue competência presidencial e limites constitucionais e legais.', ['Pedido não garante concessão.', 'Examinar vedações e possibilidade de iniciativa própria.', 'Distinguir anistia legislativa.'], 'Não confundir Presidente com juiz da execução nem prometer perdão a crime legalmente excluído.', 'Condenado apresenta pedido individual para processamento pertinente.', 'Anistia depende de regime legislativo, não da mesma decisão individual.', ['Pedido garante graça? Não.', 'Graça e anistia possuem mesmo regime? Não.'], 'Clemência individual','Benefício sujeito à competência e limites próprios.',[CF])
add(735,'Pedido individual é instruído e encaminhado no regime pertinente, integrado à LEP188–191.', ['Documentos subsidiam análise.', 'Conselho não substitui decisão presidencial.'], 'Não tratar remessa ao Ministério como concessão automática.', 'Pedido documentado percorre fluxo legal de apreciação.', 'Documento faltante pode exigir esclarecimento, sem autorizar funcionário a conceder benefício.', ['Conselho concede graça sozinho? Não.', 'Documentos instruem análise? Sim.'], 'Instrução da graça','Preparação do pedido individual.')
add(736,'Relatório e parecer subsidiam análise da clemência, observadas atribuições atuais do Conselho.', ['Integrar LEP70,189–190.', 'Indulto por saúde tem exceção específica de parecer no70I.'], 'Não exigir indiscriminadamente parecer em hipótese legalmente excepcionada por saúde.', 'Órgão relata circunstâncias pertinentes para apreciação competente.', 'Pedido baseado em saúde exige conferir exceção atual antes de impor barreira documental.', ['Parecer equivale à decisão presidencial? Não.', 'Hipótese de saúde exige atenção à exceção do70I? Sim.'], 'Parecer de clemência','Subsídio consultivo conforme competência atual.')
add(737,'Processamento ministerial prepara submissão da petição à autoridade presidencial competente.', ['Autos ou peças podem ser requisitados.', 'Integrar CF84XII e limites legais.'], 'Ministro processar pedido não significa poder conceder todo benefício sem delegação válida e seus limites.', 'Documentação é preparada para apreciação pertinente.', 'Competência ou delegação deve ser conferida, não presumida por cargo administrativo.', ['Processamento é concessão automática? Não.', 'Competência deve ser verificada? Sim.'], 'Apreciação presidencial','Exame da clemência pela autoridade competente.',[CF])
add(738,'Decreto concedido exige decisão judicial que extinga pena ou ajuste execução na comutação, conforme termos aplicáveis.', ['Indulto total e redução não têm efeito idêntico.', 'Conferir abrangência do ato.'], 'Não apagar toda consequência civil ou condenatória só porque houve clemência penal.', 'Decreto reduz pena e cálculo é ajustado na extensão prevista.', 'Benefício restrito a um título não apaga outras condenações fora do ato.', ['Comutação sempre extingue integralmente pena? Não.', 'Termos do decreto delimitam efeito? Sim.'], 'Comutação','Modificação da pena nos termos do ato de clemência.')
add(739,'Texto admite recusa da comutação; distinguir benefício modificativo e suas condições.', ['Examinar ato e regime pertinente.', 'Recusa não cria perdão integral alternativo.'], 'Não tratar direito de recusar como poder de escolher qualquer pena ou exigir indulto.', 'Beneficiário examina comutação concedida e formaliza recusa cabível.', 'Recusar redução não obriga Presidente a eliminar pena inteira.', ['Recusa obriga indulto total? Não.', 'Comutação difere de perdão integral? Sim.'], 'Recusa da comutação','Manifestação sobre benefício modificativo previsto.')
add(740,'Arquivamento ministerial documenta processo do pedido de graça, sem substituir cumprimento judicial do benefício concedido.', ['Distinguir autos administrativos e execução.', 'Preservar atos e documentos pertinentes.'], 'Arquivar pedido não prova concessão nem dispensa ajuste da execução.', 'Após trâmite, processo administrativo é arquivado no órgão pertinente.', 'Se concedido benefício, cópia do ato deve chegar à execução para providências.', ['Arquivamento garante concessão? Não.', 'Cumprimento judicial é questão distinta? Sim.'], 'Arquivo do pedido','Custódia administrativa da documentação da clemência.')
add(741,'Indulto coletivo exige verificar requisitos do decreto e providência judicial conforme LEP192–193.', ['Aplicar alcance temporal, exclusões e condições do ato.', 'Juízo reconhece cabimento ao caso.'], 'Não conceder a todos os presos por existir decreto nem afirmar que todo efeito da condenação desaparece.', 'Condenado elegível requer reconhecimento com cálculo e documentos.', 'Hipótese expressamente excluída não recebe benefício por analogia automática.', ['Decreto beneficia automaticamente qualquer preso? Não.', 'Requisitos do ato precisam ser conferidos? Sim.'], 'Indulto coletivo','Clemência a grupo legalmente delimitado.',[CF])
add(742,'Anistia exige integrar lei concedente e extinção da punibilidade, não apenas sentença já definitiva.', ['LEP187 disciplina reconhecimento.', 'Examinar abrangência e limites constitucionais.'], 'Anistia não é ato presidencial idêntico ao indulto e não se limita universalmente à fase pós-trânsito.', 'Lei anistia hipótese abrangida e juízo reconhece efeito pertinente.', 'Crime fora do alcance legal não recebe benefício por semelhança.', ['Anistia e indulto são atos idênticos? Não.', 'Alcance da lei concedente importa? Sim.'], 'Anistia','Benefício legislativo com alcance definido.',[CF])
add(743,'Reabilitação segue CP94: prazo atual de dois anos, com requisitos e cômputo dos períodos de benefício sem revogação.', ['Não recuperar quatro ou oito anos históricos.', 'Pedido ao juiz da condenação.', 'Indicar residência e comprovar requisitos.'], 'Prazo sozinho não garante deferimento; não confundir com revisão criminal ou absolvição.', 'Pena extinta e prazo legal atendido permitem examinar pedido documentado.', 'Reincidência não autoriza usar oito anos antigos como regra automática atual.', ['Prazo atual comum é quatro ou oito anos? Não.', 'Reabilitação equivale à absolvição? Não.'], 'Reabilitação','Proteção legal de registros e efeitos delimitados da condenação.')
add(744,'Documentos devem demonstrar requisitos atuais do CP94, integrados à instrução do CPP.', ['Domicílio, comportamento e reparação ou alternativa legal.', 'Renúncia da vítima ou novação podem integrar prova do dano.'], 'Não limitar análise apenas ao pagamento efetivo quando CP admite impossibilidade e outras alternativas; acusações sem condenação exigem cuidado constitucional.', 'Requerente prova residência, conduta e impossibilidade absoluta de reparar.', 'Documento de renúncia da vítima é examinado no regime atual, não rejeitado só por falta de recibo.', ['Pagamento é única alternativa legal sobre dano? Não.', 'Documentos precisam demonstrar requisitos? Sim.'], 'Prova dos requisitos','Instrução da pretensão reabilitadora.')
add(745,'Juiz pode determinar diligências, preserva sigilo possível e ouve MP antes de decidir reabilitação.', ['Esclarecer requisitos sem publicidade desnecessária.', 'MP opina; juiz decide.'], 'Parecer favorável não substitui decisão nem dispensa requisitos comprovados.', 'Diligência esclarece domicílio antes de decisão fundamentada.', 'Divulgação ampla do passado não é necessária para toda verificação documental.', ['MP é ouvido antes da decisão? Sim.', 'Diligências devem ignorar sigilo? Não.'], 'Instrução sigilosa','Verificação dos requisitos sob proteção pertinente.')
add(746,'CPP prevê recurso de ofício da decisão concessiva de reabilitação.', ['Distinguir concessão e indeferimento.', 'Não presumir revogação só pelo agravo da LEP.'], 'Reabilitação é examinada pelo juiz da condenação; recurso oficial previsto não é mera extensão de todo incidente executório.', 'Concessão é encaminhada ao exame oficial previsto.', 'Negativa não entra automaticamente na mesma hipótese de recurso de ofício concessivo.', ['Texto prevê recurso de ofício na concessão? Sim.', 'Abrange automaticamente toda negativa? Não.'], 'Reexame da concessão','Exame oficial previsto para decisão reabilitadora favorável.')
add(747,'Reabilitação definitivamente concedida é comunicada ao órgão de identificação pertinente para efetivar registros.', ['Distinguir órgão histórico e estrutura atual.', 'Não apagar fisicamente todo dado por decisão administrativa.'], 'Comunicação precisa observar conteúdo e sigilo do título, não inventar absolvição.', 'Órgão recebe decisão para ajustar informação nos limites legais.', 'Dados judiciais de acesso restrito não viram inexistentes por simples mudança do cadastro.', ['Comunicação efetiva consequências registrais? Sim.', 'Reabilitação transforma condenação em absolvição? Não.'], 'Efetivação registral','Cumprimento documental da decisão reabilitadora.')
add(748,'Reabilitação protege menção aos antecedentes nos limites legais, ressalvada requisição judicial criminal pertinente.', ['Integrar CP93 e sigilo.', 'Distinguir proteção de publicidade e apagamento universal.'], 'Não afirmar que nenhuma autoridade judicial jamais pode acessar condenação reabilitada.', 'Certidão comum respeita sigilo dos registros abrangidos.', 'Requisição de juiz criminal exige exame da exceção legal e finalidade.', ['Sigilo elimina qualquer acesso judicial? Não.', 'Certidão comum deve observar proteção legal? Sim.'], 'Sigilo reabilitador','Restrição de publicidade dos registros abrangidos.')
add(749,'Negativa pode ser renovada a qualquer tempo com novos elementos dos requisitos, conforme CP94parágrafo único.', ['Espera antiga de dois anos não é regra atual.', 'Novo pedido precisa de elementos pertinentes.'], 'Não confundir dois anos para pedido inicial com intervalo obrigatório após toda negativa.', 'Falta documental é suprida e novo pedido reúne prova pertinente.', 'Repetir pedido sem novos elementos não demonstra atendimento do regime atual.', ['Toda negativa obriga esperar mais dois anos? Não.', 'Renovação exige novos elementos pertinentes? Sim.'], 'Renovação reabilitadora','Novo exame com elementos comprobatórios atuais.')
add(750,'Revogação da reabilitação exige CP95, não remissão histórica ao antigo120.', ['Condenação definitiva como reincidente.', 'Pena que não seja apenas multa.', 'Ofício ou requerimento ministerial no regime legal.'], 'Não revogar por mera investigação nem por qualquer condenação sem preencher requisitos atuais.', 'Nova condenação definitiva como reincidente a pena não pecuniária exige exame do95.', 'Condenação só a multa não satisfaz automaticamente a hipótese.', ['Mera investigação revoga reabilitação? Não.', 'Só multa preenche automaticamente CP95? Não.'], 'Revogação reabilitadora','Perda do benefício nas hipóteses atuais.')
add(751,'Modelo de impor medida por periculosidade depois da condenação exige integração ao sistema atual, sem recuperar pena e medida cumuladas.', ['CP96–98 e LEP183 têm pressupostos próprios.', 'Tratamento superveniente não é punição extra livre.'], 'Não criar medida adicional só por avaliação vaga de perigo ou omissão da sentença.', 'Saúde mental superveniente exige avaliação e decisão legal individualizada.', 'Mau comportamento não vira automaticamente inimputabilidade e medida cumulativa.', ['Periculosidade vaga cria punição extra? Não.', 'Regime atual exige pressupostos próprios? Sim.'], 'Sistema atual de medidas','Aplicação legal delimitada distinta do modelo histórico.')
add(752,'Trânsito em julgado não autoriza completar sentença com medida detentiva antiga sem base atual.', ['Não recuperar hipóteses do751 automaticamente.', 'Respeitar título e garantias.'], 'Omissão histórica de medida não abre autorização genérica para adicionar sanção após decisão definitiva.', 'Necessidade de cuidado é examinada na via legal atual.', 'Pessoa condenada não recebe medida extra apenas porque execução ainda não começou.', ['Execução não iniciada libera imposição arbitrária? Não.', 'Título e requisitos atuais continuam necessários? Sim.'], 'Limites após trânsito','Proteção contra acréscimo punitivo sem base legal.')
add(753,'Absolvição definitiva não permite impor medida posteriormente só porque lei antiga presumia pessoa perigosa.', ['Distinguir absolvição própria e imprópria.', 'Medida exige título e pressupostos atuais.'], 'Não transformar absolvido em internado penal por presunção genérica nem ignorar coisa julgada.', 'Absolvição própria sem título de medida não vira internação por simples relatório posterior.', 'Absolvição imprópria com medida legalmente imposta tem regime executório específico.', ['Perigo presumido basta para medida após qualquer absolvição? Não.', 'Absolvição própria e imprópria precisam ser distinguidas? Sim.'], 'Título da medida','Fundamento judicial atual da execução de segurança.')
add(754,'Competência para medida deve seguir organização atual e LEP66, sem validar hipóteses históricas dos751–753.', ['Distinguir imposição e execução.', 'Competência não supre requisito material.'], 'Ser juiz competente não permite impor medida proibida por falta de título ou pressuposto.', 'Juízo executório decide incidente legal pertinente à medida vigente.', 'Remissão ao753 não legitima nova medida após absolvição própria.', ['Competência elimina necessidade de base legal? Não.', 'Imposição e execução são questões distintas? Sim.'], 'Competência da medida','Órgão atual dentro dos limites materiais legais.')
add(755,'Iniciativa judicial ou ministerial não permite restaurar modelo de segurança dos751–753.', ['Notícia da direção demanda apuração pertinente.', 'Não confundir pedido e decisão válida.'], 'Relatório de perigo não cria internação automática, nem dispensa defesa e avaliação.', 'Diretor comunica quadro de saúde para providência legal adequada.', 'Notícia de indisciplina não autoriza nova medida cumulada por vontade administrativa.', ['Relatório impõe medida sozinho? Não.', 'Provocação precisa de base atual? Sim.'], 'Comunicação para apuração','Informação que exige avaliação legal adequada.')
add(756,'Dispensa antiga de nova audiência não autoriza eliminar defesa em incidente atual de saúde ou medida.', ['Garantir contraditório e defesa cabíveis.', 'Não aplicar remissão automática ao modelo751/752.'], 'Oitiva dispensada no texto histórico não equivale a autorização para impor medida atual secreta.', 'Defesa participa do incidente que afeta execução e apresenta dados médicos.', 'Urgência clínica permite cuidados legalmente cabíveis, sem apagar revisão judicial e garantias.', ['Regra antiga elimina toda defesa atual? Não.', 'Urgência dispensa qualquer controle posterior? Não.'], 'Defesa no incidente','Participação na decisão que afeta liberdade.')
add(757,'Rito histórico de investigação de periculosidade exige integração às garantias e procedimentos atuais.', ['Não confundir três dias antigos com prazo universal de todo incidente.', 'Defesa técnica não depende apenas de pedido do acusado.', 'Conferir LEP e CPP pertinentes.'], 'Fuga não permite eliminar indiscriminadamente defesa técnica nem provar periculosidade por ausência.', 'Incidente legalmente cabível é instruído com avaliação e defesa.', 'Pessoa ausente mantém defesa pertinente, não recebe medida pela mera evasão.', ['Defesa técnica existe apenas se requerida? Não.', 'Ausência prova automaticamente periculosidade? Não.'], 'Instrução garantida','Apuração individualizada sob defesa e base legal.')
add(758,'Execução de medida válida compete ao juízo executório no regime atual da LEP.', ['Título, guia e condições precisam ser conferidos.', 'Não recuperar imposição inválida por regra de competência.'], 'Executar medida não é conceder competência para internação sem fundamento legal.', 'Juízo acompanha medida judicial válida e reavaliações pertinentes.', 'Documento sem título válido não permite custódia só porque chegou à execução.', ['Execução exige título válido? Sim.', 'Competência autoriza medida sem pressupostos? Não.'], 'Execução da medida','Cumprimento jurisdicional de título de segurança válido.')
add(759,'Curadoria e exame do modelo753 não autorizam internação imediata após absolvição própria.', ['Avaliação de saúde e proteção têm regimes atuais.', 'Curador não substitui defesa técnica universalmente.'], 'Não usar internação histórica desde logo como resposta automática a laudo ou condição pessoal.', 'Necessidade clínica é encaminhada à providência legal adequada com garantias.', 'Pessoa absolvida não perde liberdade penal só porque curador foi nomeado.', ['Nomear curador permite internar penalmente qualquer absolvido? Não.', 'Cuidado em saúde exige regime legal atual? Sim.'], 'Proteção e liberdade','Cuidado que não cria punição penal sem título.')
add(760,'Remissão à periculosidade do antigo CP78§3 exige leitura do regime atual, pois CP78 hoje trata de sursis.', ['Conferir correspondência material, não só número.', 'Aplicar CP96–98 e LEP nas medidas cabíveis.'], 'Não misturar condição do sursis atual com investigação histórica de medida de segurança.', 'Estudo identifica que o número remete a texto antigo e consulta regime vigente.', 'Condição de sursis não vira presunção legal de perigo por remissão desatualizada.', ['CP78 atual tem o mesmo conteúdo histórico referido? Não.', 'Número sozinho basta para aplicar remissão? Não.'], 'Remissão histórica','Referência que precisa de correspondência normativa atual.')
assert len(rows)==28
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'clemency rehabilitation units reviewed')
